probes.setupSop:
@box_a fact
  holds sealed_vaccine_box box_a
  valid timeless
@log_a fact
  holds complete_log box_a
  valid timeless
@seal_a fact
  holds seal_intact box_a
  valid timeless

probes.querySop:
@q query
  where routine_transfer_eligible box_a
@m recall
  query $q
@answer reason
  query $q
  memory $m

